  else if(o.type==='rect'){n=figma.createRectangle();n.cornerRadius=o.r||0;n.fills=o.fill?[solid(o.fill)]:[];}
  else {n=figma.createFrame();n.fills=o.fill?[solid(o.fill)]:[];if(o.r)n.cornerRadius=o.r;}
  if(o.name)n.name=o.name;
  if(o.w!==undefined)n.resize(o.w,o.h);
  if(o.stroke){n.strokes=[solid(o.stroke)];n.strokeWeight=o.sw||1;n.strokeAlign='INSIDE';}
  if(o.opacity!==undefined)n.opacity=o.opacity;
  n.x=o.x||0;n.y=o.y||0;
  if(o.parent)o.parent.appendChild(n);
  if(o.type==='text'&&o.w){n.textAutoResize='HEIGHT';n.resize(o.w,o.lh);if(o.align)n.textAlignHorizontal=o.align;}
